initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let currentSort = { field: 'accuracy', direction: 'desc' };
  let accuracyChart = null;
  let comparisonChart = null;

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // ランキングテーブルの再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((item, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${item.店舗名 || '-'}</td>
        <td>${item.カテゴリ || '-'}</td>
        <td style="color: ${item.精度 >= 80 ? '#4ade80' : item.精度 >= 60 ? '#fbbf24' : '#ef4444'};">${item.精度}%</td>
        <td>${item.MAPE}%</td>
        <td>${item.RMSE}</td>
      </tr>
    `).join('');
  }

  // データソート
  function sortData(data, field, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[field];
      let bVal = b[field];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // 予測精度推移グラフの描画
  function drawAccuracyChart() {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    // 背景をクリア
    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const dates = ['1/10', '1/11', '1/12', '1/13', '1/14', '1/15', '1/16'];
    const accuracies = [82, 85, 83, 87, 84, 86, 85];

    const padding = 50;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = height - padding - (chartHeight * i / 5);
      const value = 60 + (i * 8);
      ctx.fillText(value + '%', padding - 10, y + 4);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    dates.forEach((date, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      ctx.fillText(date, x, height - padding + 20);
    });

    // データライン描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    accuracies.forEach((acc, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((acc - 60) / 40 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    accuracies.forEach((acc, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((acc - 60) / 40 * chartHeight);
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // 予測vs実績比較チャートの描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);

    const dates = ['1/10', '1/11', '1/12', '1/13', '1/14', '1/15', '1/16'];
    const predicted = [120, 135, 128, 142, 138, 145, 140];
    const actual = [115, 140, 125, 145, 135, 148, 138];

    const padding = 50;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = height - padding - (chartHeight * i / 5);
      const value = 100 + (i * 20);
      ctx.fillText(value, padding - 10, y + 4);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    dates.forEach((date, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      ctx.fillText(date, x, height - padding + 20);
    });

    // 予測値ライン
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    predicted.forEach((val, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((val - 100) / 50 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 実績値ライン
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actual.forEach((val, i) => {
      const x = padding + (chartWidth * i / (dates.length - 1));
      const y = height - padding - ((val - 100) / 50 * chartHeight);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 150, 20, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', width - 130, 25);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(width - 150, 40, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', width - 130, 45);
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loading = container.querySelector('#loading');
    if (show) {
      loading.classList.remove('hidden');
    } else {
      loading.classList.add('hidden');
    }
  }

  // データ読み込み
  async function loadData() {
    try {
      showLoading(true);

      // 需要予測結果データを取得
      const predictionData = await window.aivicApi.list(8);
      if (predictionData) {
        // サンプルデータで精度ランキングを生成
        const rankingData = [
          { 店舗名: '店舗A', カテゴリ: '食品', 精度: 87, MAPE: 13.2, RMSE: 11.5 },
          { 店舗名: '店舗B', カテゴリ: '飲料', 精度: 82, MAPE: 18.1, RMSE: 14.2 },
          { 店舗名: '店舗C', カテゴリ: '日用品', 精度: 75, MAPE: 25.3, RMSE: 18.7 },
          { 店舗名: '店舗D', カテゴリ: '食品', 精度: 91, MAPE: 9.2, RMSE: 8.3 },
          { 店舗名: '店舗E', カテゴリ: '飲料', 精度: 78, MAPE: 22.1, RMSE: 16.9 }
        ];

        currentData = sortData(rankingData, currentSort.field, currentSort.direction);
        renderRankingTable(currentData);
      }
    } catch (error) {
      showError('データの読み込みに失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // フィルター適用
  async function applyFilters() {
    const period = container.querySelector('#period-filter').value;
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    try {
      showLoading(true);

      // フィルター条件に基づいてデータを絞り込み
      let filteredData = [...currentData];

      if (storeId) {
        const store = tables[1]?.records?.find(s => s.店舗ID === storeId);
        if (store) {
          filteredData = filteredData.filter(item => item.店舗名 === store.店舗名);
        } else {
          showError('指定された店舗が見つかりません');
          return;
        }
      }

      if (category) {
        filteredData = filteredData.filter(item => item.カテゴリ === category);
      }

      if (filteredData.length === 0) {
        showError('指定された期間にはデータが存在しません');
      }

      renderRankingTable(filteredData);

    } catch (error) {
      showError('フィルターの適用に失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // レポート出力
  async function exportReport() {
    try {
      showLoading(true);

      // CSVデータ生成
      const headers = ['順位', '店舗名', 'カテゴリ', '精度(%)', 'MAPE(%)', 'RMSE'];
      const csvData = [
        headers.join(','),
        ...currentData.map((item, index) => [
          index + 1,
          item.店舗名,
          item.カテゴリ,
          item.精度,
          item.MAPE,
          item.RMSE
        ].join(','))
      ].join('\n');

      // ダウンロード
      const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '予測精度レポート_' + new Date().toISOString().split('T')[0] + '.csv';
      link.click();

    } catch (error) {
      showError('レポート出力に失敗しました: ' + error.message);
    } finally {
      showLoading(false);
    }
  }

  // 初期化
  initStoreOptions();
  loadData();

  // グラフ描画（初期化後に実行）
  setTimeout(() => {
    drawAccuracyChart();
    drawComparisonChart();
  }, 100);

  // イベントリスナー
  container.querySelector('#btn-apply-filters').addEventListener('click', applyFilters);
  container.querySelector('#btn-export-report').addEventListener('click', exportReport);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // テーブルソート
  container.addEventListener('click', (e) => {
    const sortBtn = e.target.closest('th[data-sort]');
    if (sortBtn) {
      const field = sortBtn.dataset.sort;
      const fieldMap = {
        'rank': '精度',
        'store': '店舗名',
        'category': 'カテゴリ',
        'accuracy': '精度',
        'mape': 'MAPE',
        'rmse': 'RMSE'
      };

      if (currentSort.field === fieldMap[field]) {
        currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
      } else {
        currentSort.field = fieldMap[field];
        currentSort.direction = 'desc';
      }

      const sortedData = sortData(currentData, currentSort.field, currentSort.direction);
      renderRankingTable(sortedData);
    }
  });

  // グラフ期間切り替え
  container.querySelector('#btn-daily').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  container.querySelector('#btn-weekly').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  container.querySelector('#btn-monthly').addEventListener('click', () => {
    drawAccuracyChart();
    drawComparisonChart();
  });

  // ウィンドウリサイズ時のグラフ再描画
  window.addEventListener('resize', () => {
    setTimeout(() => {
      drawAccuracyChart();
      drawComparisonChart();
    }, 100);
  });
}
